// Command panic is a plugin that panics once it is connected.
package main

import (
	"context"

	"github.com/USA-RedDragon/DMRHub/sdk/plugin"
	pluginv1 "github.com/USA-RedDragon/DMRHub/sdk/plugin/v1"
)

func main() {
	plugin.MainWith(&pluginv1.Hello{Name: "Panic"}, func(context.Context, *plugin.Conn) error {
		panic("the panic of the test plugin")
	})
}
